        seq,recs=S.read_export(f,depot); P.append((seq,f,recs))
    P.sort(key=lambda p:p[0])
    cur={}; c=collections.Counter()
    for _,f,recs in P:
        for r in recs:
            if r.type=='new':
                if r.num in cur: c['resend']+=1
                else: cur[r.num]=r
            elif r.type=='correction':
                if r.num not in cur: c['corr_nocur']+=1
                cur[r.num]=r; c['corr']+=1
            else:
                if r.num not in cur: c['void_nocur']+=1
                cur.pop(r.num,None); c['void']+=1
